# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">VİRÜSLERİN YAPISI (BAKTERİYOFAJ MODELİ) VE ÖZELLİKLERİ</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">VİRÜS (BAKTERİYOFAJ) ŞEMASI</text>\n  <polygon points="180,78 215,96 215,130 180,148 145,130 145,96" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="2"/>\n  <path d="M165,105 Q180,92 195,105 Q165,118 195,126" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <rect x="172" y="148" width="16" height="38" fill="#93c5fd" stroke="#1d4ed8" stroke-width="1.5"/>\n  <line x1="172" y1="186" x2="140" y2="215" stroke="#1d4ed8" stroke-width="2"/>\n  <line x1="188" y1="186" x2="220" y2="215" stroke="#1d4ed8" stroke-width="2"/>\n  <line x1="175" y1="186" x2="155" y2="218" stroke="#1d4ed8" stroke-width="2"/>\n  <line x1="185" y1="186" x2="205" y2="218" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="40" y="102" font-size="10.5" font-weight="bold" fill="#1e3a8a">Kapsid (Protein Kılıf)</text>\n  <text x="40" y="125" font-size="10.5" font-weight="bold" fill="#b91c1c">Genom (DNA veya RNA)</text>\n  <text x="40" y="168" font-size="10.5" font-weight="bold" fill="#1e3a8a">Boyun ve Kuyruk</text>\n  <text x="40" y="205" font-size="10.5" font-weight="bold" fill="#1e3a8a">Tutunma İplikleri</text>\n  <rect x="355" y="45" width="320" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">NEDEN HÜCRESEL CANLI DEĞİLDİR?</text>\n  <text x="372" y="95" font-size="11" font-weight="bold" fill="#7f1d1d">• Hücre zarı, sitoplazma ve ribozomları YOKTUR.</text>\n  <text x="372" y="120" font-size="11" font-weight="bold" fill="#7f1d1d">• ATP üretemez, beslenemez, büyüyemez.</text>\n  <text x="372" y="145" font-size="11" font-weight="bold" fill="#7f1d1d">• Bağımsız metabolizma ve homeostazisi YOKTUR.</text>\n  <text x="372" y="170" font-size="11" font-weight="bold" fill="#7f1d1d">• Konak hücre dışında kristalleşir (cansız özellik).</text>\n  <text x="372" y="195" font-size="11" font-weight="bold" fill="#166534">• Zorunlu hücre içi parazittir; konak içinde çoğalır.</text>\n  <text x="372" y="220" font-size="11" font-weight="bold" fill="#166534">• Nükleik asit + protein bulundurur ve mutasyona uğrar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">VİRÜSLERİN CANLILAR VE CANSIZLARLA ORTAK ÖZELLİKLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">CANSIZLARLA BENZER ÖZELLİKLERİ</text>\n  <text x="42" y="96" font-size="11.5" fill="#78350f">1. Hücresel yapıya (zar, sitoplazma, organel) sahip olmama</text>\n  <text x="42" y="122" font-size="11.5" fill="#78350f">2. Konak hücre dışında kristal hâle geçebilme</text>\n  <text x="42" y="148" font-size="11.5" fill="#78350f">3. Enzim sistemleri olmadığı için ATP sentezleyememe</text>\n  <text x="42" y="174" font-size="11.5" fill="#78350f">4. Beslenme, büyüme, boşaltım ve solunum yapamama</text>\n  <text x="42" y="200" font-size="11.5" fill="#78350f">5. Antibiyotiklerden etkilenmeme (hedef metabolizma yok)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">CANLILARLA BENZER ÖZELLİKLERİ</text>\n  <text x="377" y="96" font-size="11.5" fill="#14532d">1. Kalıtım materyali (DNA ya da RNA) ve protein taşıma</text>\n  <text x="377" y="122" font-size="11.5" fill="#14532d">2. Uygun bir konak hücre içinde çoğalabilme (replikasyon)</text>\n  <text x="377" y="148" font-size="11.5" fill="#14532d">3. Kendine özgü kuyruk/tutunma enzimi bulundurabilme</text>\n  <text x="377" y="174" font-size="11.5" fill="#14532d">4. Mutasyona uğrayarak kalıtsal çeşitlilik (varyasyon) kazanma</text>\n  <text x="377" y="200" font-size="11.5" fill="#14532d">5. Belirli bir konak hücreye veya dokuya özgüllük gösterme</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. TEMA BÜTÜNCÜL ÖZETİ: BİLİMİN DOĞASI VE YAŞAMIN ÖZELLİKLERİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">BİLİMSEL ARAŞTIRMA SÜRECİ</text>\n  <text x="32" y="94" font-size="11" fill="#1e3a8a">• Gözlem (Nitel ve Nicel)</text>\n  <text x="32" y="116" font-size="11" fill="#1e3a8a">• Problem ve Hipotez Kurma</text>\n  <text x="32" y="138" font-size="11" fill="#1e3a8a">• Tahmin (Eğer... ise...)</text>\n  <text x="32" y="160" font-size="11" fill="#1e3a8a">• Kontrollü Deney (Bağımsız</text>\n  <text x="40" y="176" font-size="11" fill="#1e3a8a">ve Bağımlı Değişken)</text>\n  <text x="32" y="198" font-size="11" fill="#1e3a8a">• Veri Analizi ve Çıkarım</text>\n  <text x="32" y="220" font-size="11" fill="#1e3a8a">• Teori (Neden) ve Kanun (Nasıl)</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">CANLILARIN ORTAK ÖZELLİKLERİ</text>\n  <text x="257" y="94" font-size="11" fill="#14532d">• Hücresel Yapı (Prokaryot/Ökaryot)</text>\n  <text x="257" y="116" font-size="11" fill="#14532d">• Organizasyon ve Homeostazi</text>\n  <text x="257" y="138" font-size="11" fill="#14532d">• Beslenme ve ATP Üretimi/Tüketimi</text>\n  <text x="257" y="160" font-size="11" fill="#14532d">• Metabolizma (Anabolizma/Katabolizma)</text>\n  <text x="257" y="182" font-size="11" fill="#14532d">• Boşaltım ve Uyarılara Tepki</text>\n  <text x="257" y="204" font-size="11" fill="#14532d">• Büyüme, Gelişme ve Üreme</text>\n  <text x="257" y="224" font-size="11" fill="#14532d">• Varyasyon ve Adaptasyon</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#faf5ff" stroke="#a855f7" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">ÜÇ DOMEN VE VİRÜSLER</text>\n  <text x="482" y="94" font-size="11" fill="#581c87">• Bakteriler (Prokaryot, Peptidoglikan)</text>\n  <text x="482" y="116" font-size="11" fill="#581c87">• Arkeler (Prokaryot, Ekstrem koşul)</text>\n  <text x="482" y="138" font-size="11" fill="#581c87">• Ökaryotlar (Protista, Bitki,</text>\n  <text x="490" y="154" font-size="11" fill="#581c87">Mantar, Hayvan âlemleri)</text>\n  <text x="482" y="180" font-size="11" font-weight="bold" fill="#b91c1c">• Virüsler: Hücresel olmadığı için</text>\n  <text x="490" y="198" font-size="11" font-weight="bold" fill="#b91c1c">3 domenin hiçbirinde yer almaz;</text>\n  <text x="490" y="216" font-size="11" font-weight="bold" fill="#b91c1c">biyolojik varlık (geçiş formu).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
